  const rows=NEXUS_AI_ARCHITECTURE.map(x=>'<tr><td><b>'+esc(x[0])+'</b></td><td>'+esc(x[1])+'</td><td><span class="pill">RBAC + POLICY + AUDIT</span></td></tr>').join('');
